# %% ../nbs/00_core.ipynb #2edea58c
@dataclass(frozen=True)
class Finding:
    "One tool-route problem in a recorded turn."
    kind: str
    tool: str
    index: int
    message: str

@dataclass(frozen=True)
class Assessment:
    "The route score and findings for one or more turns."
    score: int
    calls: int
    findings: tuple[Finding, ...]

# %% ../nbs/00_core.ipynb #8e5631ea
RAMABANA_HISTORY = Path.home()/'.config/ramabana/agent-history.jsonl'

def _loads(s):
    try: return json.loads(s)
    except (json.JSONDecodeError, TypeError): return None

def read_history(
    path=RAMABANA_HISTORY, # Ramabana `agent-history.jsonl` path
    session=None,         # optional session id
):
    "Read completed Ramabana turns in append order, skipping partial lines."
    r = L(Path(path).expanduser().readlines()).map(_loads).filter(lambda x: isinstance(x, dict))
    return r if not session else r.filter(lambda x: x.get('session')==session)

def tool_args(action):
    "The call arguments of `action` as a dict."
    a = action.get('args')
    if isinstance(a, str): a = _loads(a)
    return a if isinstance(a, dict) else {}

# %% ../nbs/00_core.ipynb #cf182995
_RESEARCH_TOOLS = {'web_search', 'read_url', 'search_code', 'run_shell'}
_SCHEMA_ERRS = ('could not parse commands', 'JSONDecodeError', 'JSON decoder')
SHELL_TOOLS = (
    (r'git\s+status\b', 'git_status'), (r'git\s+diff\b', 'git_diff'), (r'git\s+(log|show)\b', 'git_log'),
    (r'git\s+commit\b', 'git_commit'), (r'git\s+(checkout|switch)\b', 'git_checkout'), (r'git\s+stash\b', 'git_stash'),
    (r'git\s+(push|pull|fetch)\b', 'git_remote'), (r'(rg|grep|ag)\b', 'grep'), (r'(find|fd)\b', 'ls'), (r'(ls|tree)\b', 'ls'),
    (r'(sed|perl)\s+-p?i\b', 'replace_text'), (r'(cat\s*>|tee\b)', 'create_file'), (r'sed\s+-n\b|(cat|head|tail|nl)\b', 'view_file'),
    (r'(curl|wget)\b', 'read_url'))
_PREFIX = re.compile(r'^(env(\s+-u\s+\S+|\s+\w+=\S+)*\s+|(\w+=\S+\s+)+)')
_GIT_OPTS = re.compile(r'^git\s+((-[Cc]\s+\S+|--\S+)\s+)+')

def _segments(command):
    for s in re.split(r'&&|;|\|\|', command):
        s = _GIT_OPTS.sub('git ', _PREFIX.sub('', s.strip()))
        if s and not s.startswith('cd '): yield s.split('|')[0].strip()

def bypass_tool(command, offered=None):
    "The dedicated tool `command` stands in for, if any."
    if not command: return None
    if re.search(r'&\s*$', command.strip()) and not command.strip().endswith('&&'): hit = 'run_shell_bg'
    else: hit = next((t for s in _segments(command) for rx,t in SHELL_TOOLS if re.match(rx, s)), None)
    return hit if hit and (offered is None or hit in offered) else None

def _is_fossick_repo(action):
    text = ' '.join(str(v) for v in tool_args(action).values())
    return action.get('tool') == 'run_shell' and 'fossick read-gh-repo' in text

def _first_research_finding(prompt, activities):
    if 'github' not in prompt.lower() or 'fossick' not in prompt.lower(): return None
    research = ((i, action) for i, action in enumerate(activities) if action.get('tool') in _RESEARCH_TOOLS)
    index, action = next(research, (None, None))
    if action is None or _is_fossick_repo(action): return None
    return Finding('route', action.get('tool', ''), index, 'Use fossick read-gh-repo as the first repository research call.')

def _failure_key(action): return (action.get('tool', ''), json.dumps(tool_args(action), sort_keys=True, default=str))

_DENIED = 'Denied by human operator'

def denial_reason(action):
    "The operator's reason if `action` is a refused ask, else `None`."
    if action.get('ok') is not False: return None
    detail = str(action.get('detail') or '')
    if action.get('kind') != 'ask' and not detail.startswith(_DENIED): return None
    return detail.partition('Reason given:')[2].strip() or 'no reason given'

def _failure_findings(index, action, failed):
    if action.get('ok') is not False or denial_reason(action) is not None: return ()
    tool, detail, findings = action.get('tool', ''), str(action.get('detail', '')), []
    key = _failure_key(action)
    if key in failed: findings.append(Finding('repeat_failure', tool, index, 'Diagnose or change route before repeating a failed call.'))
    failed.add(key)
    if any(s in detail for s in _SCHEMA_ERRS):
        findings.append(Finding('schema', tool, index, 'Send arguments that match the tool schema exactly.'))
    if tool == 'run_shell' and ('usage:' in detail or 'unrecognized arguments' in detail):
        findings.append(Finding('tool_protocol', tool, index, 'Read the project command contract before retrying.'))
    return tuple(findings)

def _denial_finding(index, action, denied):
    key, retry = _failure_key(action), None
    if key in denied: retry = Finding('denial_retry', action.get('tool', ''), index, 'Ask the user about the refused call instead of retrying it.')
    if denial_reason(action) is not None: denied.add(key)
    return retry

def assess_turn(turn, denied=()):
    "Assess the tool route recorded in one Ramabana turn; `denied` holds calls refused in the previous turn."
    activities, findings, failed, bypassed, denied = turn.get('activity') or [], [], set(), set(), set(denied)
    route_finding = _first_research_finding(turn.get('prompt', ''), activities)
    if route_finding: findings.append(route_finding)
    for ind, a in enumerate(activities):
        if a.get('tool') == 'run_shell' and (t := bypass_tool(str(tool_args(a).get('command', '')))) and t not in bypassed:
            bypassed.add(t); findings.append(Finding('bypass', 'run_shell', ind, f'Use {t} instead of run_shell for this.'))
        if retry := _denial_finding(ind, a, denied): findings.append(retry)
        findings.extend(_failure_findings(ind, a, failed))
    return Assessment(max(0, 100 - 20*len(findings)), len(activities), tuple(findings))

def _carried(prev, turn):
    "Calls refused in `prev` that `turn` may still be retrying: same session, and no question asked in between."
    if prev is None or prev.get('session') != turn.get('session') or '?' in str(prev.get('reply') or ''): return set()
    return {_failure_key(a) for a in prev.get('activity') or [] if denial_reason(a) is not None}

def assess_history(turns):
    "Assess several turns as one route corpus, carrying refusals into the next turn of the same session."
    turns = list(turns)
    assessments = [assess_turn(t, _carried(p, t)) for p,t in zip([None]+turns, turns)]
    findings = tuple(f for a in assessments for f in a.findings)
    return Assessment(max(0, 100 - 20*len(findings)), sum(a.calls for a in assessments), findings)

