ROUND_REVISION = 1
ROUNDS_DIR = xdg_config_home()/'dhrona/rounds'
SEEDS_DIR = Path(dhrona.__file__).parent/'seeds'

def call_valid(args, fn):
    "Would `fn` accept `args` as keyword arguments?"
    try: inspect.signature(fn).bind(**args); return True
    except (TypeError, ValueError): return False

def _tool_name(f):
    if isinstance(f, str): return f
    if isinstance(f, functools.partial): return _tool_name(f.func)
    if callable(f): return getattr(f, '__name__', type(f).__name__)
    raise TypeError('tools must be tool callables, names, or a name→callable dict')

def as_tools(tools):
    "Tools keyed by name, from a dict or an iterable of callables, partials, or names (a name maps to `None`)."
    return dict(tools) if isinstance(tools, dict) else {_tool_name(f): None if isinstance(f, str) else f for f in tools}

def round_calls(rnd):
    "The `(tool, arguments)` pairs an accepted round makes."
    return [(p['name'], p.get('arguments') or {}) for m in rnd['history'] for p in m['content'] if p['type']=='tool_use']

def round_valid(rnd, tools):
    "Do all of `rnd`'s calls bind to `tools`? A `None` tool checks the name only."
    return all(n in tools and (tools[n] is None or call_valid(a, tools[n])) for n,a in round_calls(rnd))

def load_rounds(dirs=None):
    "Accepted rounds from the library and packaged seeds, skipping unreadable files."
    rs = [_loads(p.read_text()) for d in ifnone(dirs, [ROUNDS_DIR, SEEDS_DIR]) for p in sorted(Path(d).glob('*.json'))]
    return [r for r in rs if isinstance(r, dict) and r.get('meta', {}).get('status')=='accepted']

def _tc(p): return ToolCall(p['name'], p.get('arguments') or {}, **({'id': p['id']} if p.get('id') else {}))

def round_msgs(rnd):
    "Canonical Urai messages from an accepted round."
    res, tcs = [], {}
    for m in rnd['history']:
        parts = m['content']
        if m['role']=='tool':
            res += [mk_tool_res_msg(tcs.get(p.get('id')) or _tc(p), p.get('text', '')) for p in parts if p['type']=='tool_result']
            continue
        msg = {'role': m['role'], 'content': '\n'.join(p['text'] for p in parts if p['type']=='text' and p.get('text'))}
        if calls := [_tc(p) for p in parts if p['type']=='tool_use']:
            tcs.update({tc['id']: tc for tc in calls}); msg['tool_calls'] = calls
        res.append(msg)
    return res

def warm_start(tools=None, model=None, limit=2, dirs=None):
    "Canonical Urai history from accepted rounds that fit the offered tools, best-ranked and same-model first."
    rs = load_rounds(dirs)
    if tools is not None:
        tools = as_tools(tools)
        rs = [r for r in rs if round_valid(r, tools)]
    rs = sorted(rs, key=lambda r: (r['meta'].get('rank', 50), r['meta'].get('model') != model))[:limit]
    return [m for r in rs for m in round_msgs(r)]

def dhrona_version():
    "The warm-start revision."
    return f'{dhrona.__version__}:{ROUND_REVISION}'

def receipt_path(state=None):
    "The completion receipt file."
    return Path(state) if state else xdg_state_home()/'dhrona/completions.json'

def register_completion(state=None):
    "Record one clean round and return its completion id."
    path, cid = receipt_path(state), uuid.uuid4().hex
    records = path.read_json() if path.exists() else {}
    records[cid] = {'version': dhrona_version(), 'at': time.time()}
    path.write_json(records, indent=2)
    return cid

def completion_valid(cid, state=None):
    "Does `cid` name a completion for the current round?"
    path = receipt_path(state)
    if not cid or not path.exists(): return False
    return (path.read_json().get(cid) or {}).get('version') == dhrona_version()

def prepare_chat(chat, tools=None, model=None):
    "Prepend the Dhrona warm start to an empty Urai-compatible chat."
    if chat.hist: raise ValueError('Dhrona prepares an empty chat only')
    chat.hist = chat.fmt2hist(warm_start(tools, model))
    if hasattr(chat, '_recreate_conv'): chat._recreate_conv()
    return chat

# %% ../nbs/00_core.ipynb #f4e8294d
@call_parse
def main(
    history: str=str(RAMABANA_HISTORY), # Ramabana history path
    session: str=None,                  # optional session id
):
    "Assess persisted Ramabana tool routes."
    if not Path(history).expanduser().exists(): sys.exit(f'No history at {history}')
    a = assess_history(read_history(history, session))
    print(json.dumps({'score': a.score, 'calls': a.calls, 'findings': [asdict(f) for f in a.findings]}, indent=2))
